nearest.example:
kcds.core.Events.on('playerCommand', (player, command) => {
  if (command !== 'grave') {
    return;
  }
  const grave = kcds.world.Grave.nearest(player.position, 30);
  const message = grave ? `A grave ${grave.distanceTo(player.position).toFixed(0)} m away` : 'No grave nearby';
  kcds.core.Chat.sendToPlayer(player, message);
});

nearest.exampleCs:
Events.On("playerCommand", (Player player, string command) =>
{
    if (command != "grave")
    {
        return;
    }
    var grave = Grave.Nearest(player.Position, 30);
    var message = grave != null ? $"A grave {grave.DistanceTo(player.Position).ToString("F0")} m away" : "No grave nearby";
    Chat.SendToPlayer(player, message);
});

