reset.example:
// A dug grave refills after ten minutes.
kcds.core.Events.on('graveDug', (player, grave) => {
  setTimeout(() => grave.reset(), 10 * 60 * 1000);
});

reset.exampleCs:
// A dug grave refills after ten minutes.
Events.On("graveDug", (Player player, Grave grave) =>
{
    Timers.SetTimeout(() => grave.Reset(), 10 * 60 * 1000);
});
